using System;
using System.IO;
using System.Linq;
namespace DoomSNESed {
    public static class ModifiedRomTests {
        static int count;static void Check(bool ok,string message){Bin.Require(ok,"Modified ROM: "+message);count++;}
        static void Reject(Action action,string message){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,message);}
        public static void Run(string original,string output){count=0;string dir=Path.Combine(output,"modified-08"),resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data");Directory.CreateDirectory(dir);var retail=new Rom(original,resources);byte[] modified=(byte[])retail.Bytes.Clone();modified[0x1f711d]^=1;WadConverter.Checksum(modified);string source=Path.Combine(dir,"modified-2mb.sfc");File.WriteAllBytes(source,modified);var rom=new Rom(source,resources);Check(rom.IsModified&&rom.SourceHash==rom.Project.SourceSha256,"modified USA base accepted and project bound to its exact normalized hash");
            byte[] headered=new byte[modified.Length+512];Buffer.BlockCopy(modified,0,headered,512,modified.Length);string smc=Path.Combine(dir,"modified-2mb.smc");File.WriteAllBytes(smc,headered);Check(new Rom(smc,resources).Bytes.SequenceEqual(modified),"2 MiB copier header stripped");byte[] wrong=(byte[])modified.Clone();wrong[0xefd80]^=1;Reject(()=>ModifiedRom.Validate(wrong),"incompatible loader signature rejected");Reject(()=>ModifiedRom.Validate(new byte[1024]),"invalid ROM size rejected");
            rom.Project.RetailAssets=true;byte[] font=HudAssets.Data(modified,6);var fontAsset=HudAssets.All().First(a=>a.Screen==6);rom.Project.Graphics.Add(new GraphicReplacement{Screen=6,Width=fontAsset.Width,Height=fontAsset.Height,Pixels=HudAssets.Pixels(font,fontAsset.Width,fontAsset.Height)});
            var score=new ImportedMusic{Name="Round trip score",Seconds=2,Report=""};score.Notes.Add(new MusicNote{Channel=0,Program=34,Key=40,Start=0,End=1,Velocity=100});var mapping=MusicBank.Automatic(modified,score);rom.Project.Audio.Music.Add(MusicImport.Convert(score,"E1M1",6,0,true,mapping));byte[] first=rom.Compile();string firstPath=Path.Combine(dir,"first-edit.sfc");File.WriteAllBytes(firstPath,first);rom.SavePatch(Path.Combine(dir,"first-edit.dse"),first);rom.SaveProject(Path.Combine(dir,"first-edit.sned"));Check(first.Length==0x400000,"modified 2 MiB input expands for asset editing");Check(File.ReadAllBytes(source).SequenceEqual(modified),"input ROM unchanged");
            var reopened=new Rom(firstPath,resources);reopened.Project.RetailAssets=true;Check(reopened.Compile().SequenceEqual(first),"modified 4 MiB no-edit export is byte-identical");headered=new byte[first.Length+512];Buffer.BlockCopy(first,0,headered,512,first.Length);smc=Path.Combine(dir,"modified-4mb.smc");File.WriteAllBytes(smc,headered);Check(new Rom(smc,resources).Bytes.SequenceEqual(first),"4 MiB copier header stripped");Reject(()=>reopened.LoadProject(Path.Combine(dir,"first-edit.sned")),"project rejects a different base hash");
            int originalSong=Bin.U16(first,AudioRom.SongTable),firstFree=ModifiedRom.Expansion(first)[0].Start;var face=HudAssets.All().First(a=>a.Screen==9);byte[] pixels=HudAssets.Pixels(HudAssets.Data(first,9),face.Width,face.Height);pixels[0]^=1;reopened.Project.Graphics.Add(new GraphicReplacement{Screen=9,Width=face.Width,Height=face.Height,Pixels=pixels});reopened.Project.Audio.Music.Add(MusicImport.Convert(score,"E1M2",6,0,true,MusicBank.Automatic(first,score)));byte[] second=reopened.Compile();Check(second.Skip(0x200000).Take(firstFree-0x200000).SequenceEqual(first.Skip(0x200000).Take(firstFree-0x200000)),"prior expanded allocations preserved during second edit");Check(HudAssets.Data(second,6).SequenceEqual(font),"prior custom font preserved");Check(Bin.U16(second,AudioRom.SongTable)==originalSong,"prior custom song assignment preserved");var oldBlocks=AudioRom.Blocks(first,originalSong>>8);var newBlocks=AudioRom.Blocks(second,originalSong>>8);Check(oldBlocks.Count==newBlocks.Count&&oldBlocks.Select((b,i)=>b.Data.SequenceEqual(newBlocks[i].Data)&&b.Address==newBlocks[i].Address).All(v=>v),"prior custom sequence and samples preserved");
            string secondPath=Path.Combine(dir,"second-edit.sfc");File.WriteAllBytes(secondPath,second);reopened.SavePatch(Path.Combine(dir,"second-edit.dse"),second);reopened.SaveProject(Path.Combine(dir,"second-edit.sned"));var again=new Rom(secondPath,resources);again.Project.RetailAssets=true;Check(again.Compile().SequenceEqual(second),"second edited ROM reopens without sidecars");File.WriteAllText(Path.Combine(dir,"results.txt"),"PASS: "+count+" modified ROM checks, 2/4 MiB and copier headers, no-edit preservation, repeated graphics/audio edits, exact source project binding.\r\n");
        }
    }
}
